CREATE TABLE operation_keys(tenant_id uuid NOT NULL,actor_id uuid NOT NULL,request_key varchar(100) NOT NULL,operation varchar(200) NOT NULL,request_hash varchar(64) NOT NULL,resource_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,actor_id,request_key,operation));
CREATE TABLE outbox_events(event_id uuid PRIMARY KEY,event_type varchar(80) NOT NULL,event_version int NOT NULL CHECK(event_version>0),tenant_id uuid NOT NULL,branch_id uuid,aggregate_id uuid NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),correlation_id varchar(64) NOT NULL,payload jsonb NOT NULL,actor_id uuid NOT NULL,delivery_status varchar(20) NOT NULL DEFAULT 'PENDING' CHECK(delivery_status IN ('PENDING','DELIVERED')),attempts int NOT NULL DEFAULT 0 CHECK(attempts>=0),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX pending_outbox ON outbox_events(created_at,event_id) WHERE delivery_status='PENDING';
CREATE INDEX tenant_outbox ON outbox_events(tenant_id,aggregate_id,occurred_at);

CREATE TABLE suppliers(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,name varchar(200) NOT NULL,contact varchar(300),active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE TABLE parts(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,sku varchar(80) NOT NULL,name varchar(200) NOT NULL,oem_number varchar(100),manufacturer varchar(160),category varchar(100) NOT NULL,description varchar(2000),compatibility_notes varchar(2000),compatibility_verified boolean NOT NULL DEFAULT false,supplier_id uuid,currency char(3) NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),purchase_price numeric(19,2) NOT NULL CHECK(purchase_price>=0),selling_price numeric(19,2) NOT NULL CHECK(selling_price>=0),active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,sku),FOREIGN KEY(tenant_id,supplier_id) REFERENCES suppliers(tenant_id,id));
CREATE INDEX part_search ON parts(tenant_id,category,active);
CREATE TABLE branch_stock(tenant_id uuid NOT NULL,branch_id uuid NOT NULL,part_id uuid NOT NULL,on_hand numeric(15,3) NOT NULL DEFAULT 0,reserved numeric(15,3) NOT NULL DEFAULT 0,reorder_level numeric(15,3) NOT NULL DEFAULT 0,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,branch_id,part_id),FOREIGN KEY(tenant_id,part_id) REFERENCES parts(tenant_id,id),CHECK(on_hand>=0 AND reserved>=0 AND reserved<=on_hand AND reorder_level>=0));
CREATE TABLE stock_reservations(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,part_id uuid NOT NULL,work_order_id uuid NOT NULL,quantity numeric(15,3) NOT NULL CHECK(quantity>0),status varchar(20) NOT NULL CHECK(status IN ('RESERVED','RELEASED','CONSUMED')),created_by uuid NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,part_id) REFERENCES parts(tenant_id,id));
CREATE INDEX job_reservations ON stock_reservations(tenant_id,branch_id,work_order_id,status);
CREATE TABLE stock_transfers(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,source_branch_id uuid NOT NULL,destination_branch_id uuid NOT NULL,status varchar(24) NOT NULL CHECK(status IN ('REQUESTED','APPROVED','DISPATCHED','IN_TRANSIT','PARTIALLY_RECEIVED','COMPLETED','REJECTED','CANCELLED')),note varchar(1000) NOT NULL,created_by uuid NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),CHECK(source_branch_id<>destination_branch_id));
CREATE TABLE stock_transfer_items(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,transfer_id uuid NOT NULL,part_id uuid NOT NULL,quantity numeric(15,3) NOT NULL CHECK(quantity>0),received_quantity numeric(15,3) NOT NULL DEFAULT 0 CHECK(received_quantity>=0),damaged_quantity numeric(15,3) NOT NULL DEFAULT 0 CHECK(damaged_quantity>=0),version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,transfer_id) REFERENCES stock_transfers(tenant_id,id),FOREIGN KEY(tenant_id,part_id) REFERENCES parts(tenant_id,id),UNIQUE(tenant_id,transfer_id,part_id),CHECK(received_quantity+damaged_quantity<=quantity));
CREATE TABLE stock_movements(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,part_id uuid NOT NULL,movement_type varchar(40) NOT NULL,on_hand_delta numeric(15,3) NOT NULL,reserved_delta numeric(15,3) NOT NULL,reference_id uuid,reason varchar(1000) NOT NULL,actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,part_id) REFERENCES parts(tenant_id,id));
CREATE INDEX stock_ledger ON stock_movements(tenant_id,branch_id,part_id,created_at DESC,id);
CREATE TABLE transfer_history(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,transfer_id uuid NOT NULL,action varchar(40) NOT NULL,note varchar(1000) NOT NULL,actor_id uuid NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,transfer_id) REFERENCES stock_transfers(tenant_id,id));

CREATE TABLE reservation_failures(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,part_id uuid NOT NULL,work_order_id uuid NOT NULL,quantity numeric(15,3) NOT NULL,actor_id uuid NOT NULL,reason varchar(1000) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
